<template><div class="admin-page"><el-card shadow="never" class="page-header"><div><h2>操作日志</h2><p>仅记录管理员的关键变更操作</p></div><el-button @click="load">刷新</el-button></el-card><el-card shadow="never"><div class="filters"><el-select v-model="filters.module" clearable placeholder="操作模块"><el-option v-for="item in modules" :key="item" :label="item" :value="item" /></el-select><el-select v-model="filters.result" clearable placeholder="操作结果"><el-option label="成功" value="成功" /><el-option label="失败" value="失败" /></el-select><el-input v-model="filters.keyword" clearable placeholder="操作人或摘要" @keyup.enter="load" /><el-button type="primary" @click="load">筛选</el-button></div><el-table :data="rows" v-loading="loading"><el-table-column prop="operatorName" label="操作人" width="120"/><el-table-column prop="module" label="模块" width="120"/><el-table-column prop="action" label="动作" width="100"/><el-table-column prop="summary" label="操作摘要"/><el-table-column prop="result" label="结果" width="100"><template #default="{row}"><el-tag :type="row.result==='成功'?'success':'danger'">{{row.result}}</el-tag></template></el-table-column><el-table-column prop="createTime" label="时间" width="180"/></el-table></el-card></div></template>
<script setup>import { reactive, ref, onMounted } from 'vue';import { getOperationLogs } from '../../api/operationLog';const rows=ref([]),loading=ref(false),modules=['用户权限','楼栋资源','房间资源','公告管理','报修监控','系统管理'];const filters=reactive({module:'',result:'',keyword:''});const load=async()=>{loading.value=true;try{rows.value=await getOperationLogs(filters)||[]}finally{loading.value=false}};onMounted(load)</script>
<style scoped>.admin-page{max-width:1400px;margin:0 auto}.page-header{margin-bottom:20px}.page-header :deep(.el-card__body){display:flex;justify-content:space-between;align-items:center}.page-header h2{margin:0 0 6px}.page-header p{margin:0;color:var(--sub)}.filters{display:flex;gap:12px;margin-bottom:18px}.filters .el-select{width:140px}.filters .el-input{width:220px}</style>
